export interface ArtBuilding {
  readonly tx: number
  readonly ty: number
  /** Stagger before this building starts drawing, in ms. */
  readonly bd: number
  /** Transparent hit area: x, y, width, height. */
  readonly hit: readonly [number, number, number, number]
  readonly fill: string
  readonly hatch: string
  readonly strokes: readonly ArtStroke[]
}

